import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Space löschen","description":"Einen Space löschen — was dabei verschwindet und was vorher zu tun ist.","frontmatter":{"title":"Space löschen","description":"Einen Space löschen — was dabei verschwindet und was vorher zu tun ist."},"headers":[],"relativePath":"spaces/space-loeschen.md","filePath":"spaces/space-loeschen.md","lastUpdated":1786087067000}'),i={name:"spaces/space-loeschen.md"};function s(l,e,h,o,c,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="space-loschen" tabindex="-1">Space löschen <a class="header-anchor" href="#space-loschen" aria-label="Permalink to &quot;Space löschen&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">Ein gelöschter Space nimmt alles mit</p><p>Mit dem Space verschwinden <strong>alle</strong> darin enthaltenen Grids samt Einträgen, alle Ansichten, Formulare, Seiten, Portale und Flows.</p><p>Es gibt in der Anwendung <strong>keine Wiederherstellung</strong>. Prüfen Sie die Punkte unten, bevor Sie löschen.</p></div><h2 id="vorher-prufen" tabindex="-1">Vorher prüfen <a class="header-anchor" href="#vorher-prufen" aria-label="Permalink to &quot;Vorher prüfen&quot;">​</a></h2><h3 id="_1-·-daten-sichern" tabindex="-1">1 · Daten sichern <a class="header-anchor" href="#_1-·-daten-sichern" aria-label="Permalink to &quot;1 · Daten sichern&quot;">​</a></h3><p>Ziehen Sie von jedem Grid, dessen Daten Sie behalten wollen, einen <a href="/grids/csv-export">CSV-Export</a>.</p><div class="warning custom-block"><p class="custom-block-title">Was der Export nicht mitnimmt</p><ul><li><strong>Dateianhänge</strong> — separat herunterladen</li><li><strong>Verknüpfungen</strong> — kommen als Anzeigetext, nicht als Verweis</li><li><strong>Berechnete Felder</strong> — als Wert, nicht als Berechnungsvorschrift</li><li><strong>Aufbau</strong> — Ansichten, Formulare, Flows und Seiten lassen sich nicht exportieren</li></ul><p>Für einen Umzug ist ein CSV-Export deshalb keine vollständige Sicherung. Dokumentieren Sie den Aufbau, wenn Sie ihn woanders nachbauen wollen.</p></div><h3 id="_2-·-externe-links-prufen" tabindex="-1">2 · Externe Links prüfen <a class="header-anchor" href="#_2-·-externe-links-prufen" aria-label="Permalink to &quot;2 · Externe Links prüfen&quot;">​</a></h3><p>Öffnen Sie <strong>Space-Einstellungen → Links</strong>. Dort stehen alle nach außen offenen Zugänge.</p><p>Jeder davon wird unbrauchbar:</p><table tabindex="0"><thead><tr><th>Link-Typ</th><th>Folge</th></tr></thead><tbody><tr><td>Formularlinks</td><td>Verteilte Formulare funktionieren nicht mehr</td></tr><tr><td>Ansichtslinks</td><td>Geteilte Ansichten sind weg</td></tr><tr><td>Portale</td><td>Eingebettete Seiten auf Ihrer Website bleiben leer</td></tr><tr><td>Flow starten</td><td>Fremdsysteme, die den Flow aufrufen, laufen ins Leere</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Besonders kritisch: gedruckte QR-Codes und eingebettete Portale</p><p>Ein QR-Code auf einem Aushang oder ein in Ihre Website eingebettetes Portal lässt sich nicht zurückrufen. Beides zeigt nach dem Löschen ins Nichts.</p><p>Prüfen Sie, wo solche Links im Umlauf sind, bevor Sie löschen.</p></div><h3 id="_3-·-personen-informieren" tabindex="-1">3 · Personen informieren <a class="header-anchor" href="#_3-·-personen-informieren" aria-label="Permalink to &quot;3 · Personen informieren&quot;">​</a></h3><p>Unter <strong>Space teilen</strong> sehen Sie in <strong>Geteilt mit</strong>, wer Zugriff hat. Für diese Personen verschwindet der Space kommentarlos; beim Öffnen erscheint nur noch <em>Dieser Space wurde gelöscht</em>.</p><h3 id="_4-·-abhangigkeiten-in-anderen-spaces" tabindex="-1">4 · Abhängigkeiten in anderen Spaces <a class="header-anchor" href="#_4-·-abhangigkeiten-in-anderen-spaces" aria-label="Permalink to &quot;4 · Abhängigkeiten in anderen Spaces&quot;">​</a></h3><p>Verknüpfungen bestehen zwar nur innerhalb eines Space, aber ein Flow oder eine Seite in einem <strong>anderen</strong> Space kann per HTTP-Aufruf oder internem Verweis auf Inhalte zeigen. Prüfen Sie das, wenn Sie mit mehreren Spaces arbeiten.</p><h2 id="loschen" tabindex="-1">Löschen <a class="header-anchor" href="#loschen" aria-label="Permalink to &quot;Löschen&quot;">​</a></h2><ol><li>Öffnen Sie das Space-Menü.</li><li>Wählen Sie <strong>Space löschen</strong>.</li><li>Bestätigen Sie im Dialog, der den Space-Namen in Rot anzeigt.</li></ol><h2 id="alternativen-zum-loschen" tabindex="-1">Alternativen zum Löschen <a class="header-anchor" href="#alternativen-zum-loschen" aria-label="Permalink to &quot;Alternativen zum Löschen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Oft ist Archivieren die bessere Wahl</p><table tabindex="0"><thead><tr><th>Statt zu löschen …</th><th>Vorgehen</th></tr></thead><tbody><tr><td>Space wird nicht mehr gebraucht</td><td>Kategorie „Archiv&quot; zuweisen und Farbe auf Grau setzen</td></tr><tr><td>Niemand soll mehr hineinschreiben</td><td>Alle Rollen auf <strong>Ansehen</strong> setzen — das gibt zugleich Sitzplätze frei</td></tr><tr><td>Nur die Links sollen weg</td><td>Einzelne Links in der Links-Übersicht entfernen, Space behalten</td></tr><tr><td>Kosten senken</td><td>Tarif herabstufen statt löschen</td></tr></tbody></table><p>Ein archivierter Space verbraucht keine Sitzplätze, solange niemand Bearbeitungsrechte hat — und die Daten bleiben verfügbar, falls doch noch etwas gebraucht wird.</p></div><h2 id="wer-loschen-darf" tabindex="-1">Wer löschen darf <a class="header-anchor" href="#wer-loschen-darf" aria-label="Permalink to &quot;Wer löschen darf&quot;">​</a></h2><p>Das Löschen erfordert entsprechende Rechte. Fehlt der Menüpunkt, reicht Ihre <a href="/zusammenarbeit/rollen">Rolle</a> nicht aus.</p><h2 id="was-betroffene-sehen" tabindex="-1">Was Betroffene sehen <a class="header-anchor" href="#was-betroffene-sehen" aria-label="Permalink to &quot;Was Betroffene sehen&quot;">​</a></h2><p>Nach dem Löschen erscheint bei allen, die noch einen Link oder Lesezeichen haben:</p><blockquote><p><em>Dieser Space wurde gelöscht</em></p></blockquote><p>Bei entzogenem Zugriff — ohne Löschung — lautet die Meldung dagegen:</p><blockquote><p><em>Sie haben keinen Zugriff mehr auf diesen Space.</em></p></blockquote><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/csv-export">CSV-Export</a></li><li><a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a></li><li><a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></li></ul>',28)])])}const b=n(i,[["render",s]]);export{p as __pageData,b as default};
